    """Apply the legacy NVL(value, 0) numeric conversion."""
    if value is None or value == "":
        return Decimal(0)
    if isinstance(value, Decimal):
        return value
    if isinstance(value, float):
        # Use the human-readable decimal value rather than its binary expansion.
        return Decimal(str(value))
